"use client"

import type { ParseResponse } from "@/components/viewers/lib/parse-types"
import { ParseViewer } from "@/components/viewers/parse/parse-viewer"
import { PdfViewer } from "@/components/ui/pdf-viewer"
import parseSample from "@/components/viewers/sample-data/parse.json"

const PDF_URL = "/samples/bank-statement-x4uhhi7t.pdf"

// A parse of the bank-statement sample: per-page, LLM-ready markdown with the
// transactions reconstructed as a table.
const PARSE_RESULT: ParseResponse = {
  output: parseSample.output as ParseResponse["output"],
  usage: parseSample.usage as ParseResponse["usage"],
}

/**
 * Parse viewer block — the source document beside its extracted markdown, kept
 * in sync by page. `ParseViewer` owns the markdown pane (Rendered/Text toggle,
 * page controls); the document surface here is the `PdfViewer`. Scroll the
 * document and the markdown follows; page from the markdown and the document
 * scrolls to match.
 */
export function ParseViewerBlock() {
  return (
    <div className="flex h-full min-h-[680px] flex-col bg-background">
      <ParseViewer
        result={PARSE_RESULT}
        renderDocument={(handlers) => (
          <PdfViewer
            src={PDF_URL}
            bare
            downloadFileName="bank-statement.pdf"
            onVisiblePageChange={handlers.onCurrentPageChange}
            onScrollProgressChange={handlers.onScrollProgressChange}
            className="h-full"
          />
        )}
      />
    </div>
  )
}

"use client"

import { type ParseResponse } from "@/components/viewers/lib/parse-types"
import {
  type PageMarkdownDocumentHandlers,
  type PageMarkdownViewerProps,
} from "@/components/viewers/page-markdown/page-markdown-types"
import { PageMarkdownViewer } from "@/components/viewers/page-markdown/page-markdown-viewer"

export type ParseDocumentHandlers = PageMarkdownDocumentHandlers

export interface ParseViewerProps {
  result: ParseResponse | null
  isProcessing?: boolean
  renderDocument?: PageMarkdownViewerProps["renderDocument"]
  onVisiblePageChange?: (page: number) => void
}

export function ParseViewer({
  result,
  isProcessing = false,
  renderDocument,
  onVisiblePageChange,
}: ParseViewerProps) {
  const pages = result?.output?.pages ?? []
  const text = result?.output?.text || undefined

  return (
    <PageMarkdownViewer
      pages={pages}
      text={text}
      isProcessing={isProcessing}
      renderDocument={renderDocument}
      onVisiblePageChange={onVisiblePageChange}
      downloadFileName="parse-output.md"
    />
  )
}

"use client"

import * as React from "react"
import { ScanText } from "lucide-react"

import { useElementWidth } from "@/hooks/use-element-width"
import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
} from "@/components/ui/resizable"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Spinner } from "@/components/ui/spinner"
import { usePagePaneSync } from "@/components/viewers/page-markdown/page-markdown-hooks"
import {
  fitPageScale,
  joinMarkdownPages,
  zoomPageScale,
} from "@/components/viewers/page-markdown/page-markdown-model"
import { PageMarkdownPage } from "@/components/viewers/page-markdown/page-markdown-page"
import { PageMarkdownToolbar } from "@/components/viewers/page-markdown/page-markdown-toolbar"
import {
  type PageMarkdownViewerProps,
  type PageMarkdownViewMode,
} from "@/components/viewers/page-markdown/page-markdown-types"

export function PageMarkdownViewer({
  pages,
  text = joinMarkdownPages(pages),
  isProcessing = false,
  renderDocument,
  onVisiblePageChange,
  downloadFileName = "document.md",
}: PageMarkdownViewerProps) {
  const hasPages = pages.length > 0
  const [mode, setMode] = React.useState<PageMarkdownViewMode>("rendered")
  const [manualScale, setManualScale] = React.useState<number | null>(null)
  const [markdownContainerRef, markdownContainerWidth] = useElementWidth()
  const { currentPage, reportDocumentPage, reportMarkdownPage } =
    usePagePaneSync({ onMarkdownPageChange: onVisiblePageChange })

  const markdownViewportRef = React.useRef<HTMLDivElement | null>(null)
  const documentPaneRef = React.useRef<HTMLDivElement | null>(null)
  const [documentPageReport, setDocumentPageReport] = React.useState<{
    page: number
  } | null>(null)

  const scrollPaneToPage = React.useCallback(
    (ref: React.RefObject<HTMLDivElement | null>, page: number) => {
      ref.current
        ?.querySelector<HTMLElement>(`[data-page-number="${page}"]`)
        ?.scrollIntoView({ behavior: "smooth", block: "start" })
    },
    []
  )

  const handleDocumentPageChange = React.useCallback((page: number) => {
    setDocumentPageReport({ page })
  }, [])

  React.useEffect(() => {
    if (!documentPageReport) return
    const target = reportDocumentPage(documentPageReport.page)
    if (target?.pane === "markdown") {
      scrollPaneToPage(markdownViewportRef, target.page)
    }
  }, [documentPageReport, reportDocumentPage, scrollPaneToPage])

  const scrollFrameRef = React.useRef(0)
  const lastMarkdownPageRef = React.useRef(1)
  const reportVisibleMarkdownPage = React.useCallback(() => {
    scrollFrameRef.current = 0
    const viewport = markdownViewportRef.current
    if (!viewport) return

    const viewportRect = viewport.getBoundingClientRect()
    const pageMarker = viewportRect.top + viewportRect.height * 0.2
    const pageElements =
      viewport.querySelectorAll<HTMLElement>("[data-page-number]")
    let page = 1

    for (const element of pageElements) {
      if (element.getBoundingClientRect().top <= pageMarker) {
        page = Number(element.dataset.pageNumber)
      } else {
        break
      }
    }

    if (page && page !== lastMarkdownPageRef.current) {
      lastMarkdownPageRef.current = page
      const target = reportMarkdownPage(page)
      if (target?.pane === "document") {
        scrollPaneToPage(documentPaneRef, target.page)
      }
    }
  }, [reportMarkdownPage, scrollPaneToPage])

  const handleMarkdownScroll = React.useCallback(() => {
    if (scrollFrameRef.current) return
    scrollFrameRef.current = requestAnimationFrame(reportVisibleMarkdownPage)
  }, [reportVisibleMarkdownPage])

  React.useEffect(
    () => () => {
      if (scrollFrameRef.current) cancelAnimationFrame(scrollFrameRef.current)
    },
    []
  )

  const fitScale = fitPageScale(markdownContainerWidth)
  const scale = manualScale ?? fitScale

  if (!hasPages) {
    return (
      <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-4 bg-muted/30 px-8 text-muted-foreground">
        {isProcessing ? (
          <>
            <Spinner className="size-8 text-primary" />
            <p className="text-sm">Parsing document...</p>
          </>
        ) : (
          <>
            <ScanText className="size-12 opacity-60" />
            <div className="space-y-1 text-center">
              <p className="text-sm font-medium text-foreground">
                No markdown pages yet
              </p>
              <p className="max-w-xs text-xs">
                Provide page-by-page markdown to see the rendered document here.
              </p>
            </div>
          </>
        )}
      </div>
    )
  }

  const markdownPane = (
    <div className="flex h-full min-h-0 min-w-0 flex-col bg-muted/20">
      <PageMarkdownToolbar
        currentPage={Math.min(currentPage, pages.length)}
        pageCount={pages.length}
        mode={mode}
        scale={scale}
        text={text}
        downloadFileName={downloadFileName}
        onModeChange={setMode}
        onZoom={(factor) => setManualScale(zoomPageScale(scale, factor))}
        onFitWidth={() => setManualScale(null)}
      />
      <ScrollArea
        viewportRef={markdownViewportRef}
        viewportProps={{ onScroll: handleMarkdownScroll }}
        className="min-h-0 flex-1"
      >
        <div
          ref={markdownContainerRef}
          className="flex flex-col items-center gap-4 p-4"
        >
          {pages.map((markdown, index) => (
            <PageMarkdownPage
              key={`${mode}-${index}`}
              page={index + 1}
              markdown={markdown}
              mode={mode}
              scale={scale}
            />
          ))}
        </div>
      </ScrollArea>
    </div>
  )

  if (!renderDocument) {
    return <div className="flex min-h-0 flex-1 flex-col">{markdownPane}</div>
  }

  return (
    <ResizablePanelGroup orientation="horizontal" className="min-h-0 flex-1">
      <ResizablePanel defaultSize={52} minSize={28}>
        <div ref={documentPaneRef} className="h-full min-w-0">
          {renderDocument({ onCurrentPageChange: handleDocumentPageChange })}
        </div>
      </ResizablePanel>
      <ResizableHandle withHandle />
      <ResizablePanel defaultSize={48} minSize={28}>
        {markdownPane}
      </ResizablePanel>
    </ResizablePanelGroup>
  )
}

"use client"

import * as React from "react"
import { Maximize, Minus, Plus } from "lucide-react"

import { useElementWidth } from "@/hooks/use-element-width"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  MarkdownActionButtons,
  MarkdownActionsMenu,
} from "@/components/viewers/page-markdown/page-markdown-actions"
import { type PageMarkdownViewMode } from "@/components/viewers/page-markdown/page-markdown-types"

export function PageMarkdownToolbar({
  currentPage,
  pageCount,
  mode,
  scale,
  text,
  downloadFileName,
  onModeChange,
  onZoom,
  onFitWidth,
}: {
  currentPage: number
  pageCount: number
  mode: PageMarkdownViewMode
  scale: number
  text: string
  downloadFileName: string
  onModeChange: (mode: PageMarkdownViewMode) => void
  onZoom: (factor: number) => void
  onFitWidth: () => void
}) {
  const [toolbarRef, toolbarWidth] = useElementWidth()
  const isCompact = toolbarWidth !== null && toolbarWidth < 460

  return (
    <div
      ref={toolbarRef}
      className="no-scrollbar flex h-10 shrink-0 items-center gap-1 overflow-x-auto border-b bg-card px-2"
    >
      <div className="flex min-w-0 shrink-0 items-center gap-1">
        <span className="px-1 text-xs whitespace-nowrap text-muted-foreground tabular-nums">
          Page {currentPage} of {pageCount}
        </span>
        <ModeTabs mode={mode} onChange={onModeChange} />
      </div>
      <div className="ml-auto flex shrink-0 items-center gap-1">
        <ToolbarIconButton label="Zoom out" onClick={() => onZoom(1 / 1.2)}>
          <Minus />
        </ToolbarIconButton>
        <span className="w-12 text-center text-xs text-muted-foreground tabular-nums">
          {Math.round(scale * 100)}%
        </span>
        <ToolbarIconButton label="Zoom in" onClick={() => onZoom(1.2)}>
          <Plus />
        </ToolbarIconButton>
        <ToolbarIconButton label="Fit width" onClick={onFitWidth}>
          <Maximize />
        </ToolbarIconButton>
        <Separator orientation="vertical" className="mx-1 h-4" />
        {isCompact ? (
          <MarkdownActionsMenu text={text} fileName={downloadFileName} />
        ) : (
          <MarkdownActionButtons text={text} fileName={downloadFileName} />
        )}
      </div>
    </div>
  )
}

function ModeTabs({
  mode,
  onChange,
}: {
  mode: PageMarkdownViewMode
  onChange: (mode: PageMarkdownViewMode) => void
}) {
  return (
    <Tabs
      value={mode}
      onValueChange={(value) => onChange(value as PageMarkdownViewMode)}
    >
      <TabsList variant="underline" className="py-0">
        <TabsTrigger value="rendered" className="h-8 text-xs sm:text-xs">
          Rendered
        </TabsTrigger>
        <TabsTrigger value="text" className="h-8 text-xs sm:text-xs">
          Text
        </TabsTrigger>
      </TabsList>
    </Tabs>
  )
}

function ToolbarIconButton({
  label,
  children,
  ...props
}: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      aria-label={label}
      title={label}
      {...props}
    >
      {children}
    </Button>
  )
}

"use client"

import * as React from "react"
import { Check, Copy, Download, MoreHorizontal } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

type CopyStatus = "idle" | "copied" | "failed"

export function MarkdownActionButtons({
  text,
  fileName,
}: {
  text: string
  fileName: string
}) {
  return (
    <>
      <CopyMarkdownButton text={text} />
      <DownloadMarkdownButton text={text} fileName={fileName} />
    </>
  )
}

export function MarkdownActionsMenu({
  text,
  fileName,
}: {
  text: string
  fileName: string
}) {
  const copy = useCopyMarkdown(text)

  return (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger asChild>
        <Button
          variant="ghost"
          size="icon-sm"
          className="size-7"
          aria-label="More markdown actions"
          title="More markdown actions"
        >
          <MoreHorizontal />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-44">
        <DropdownMenuItem onSelect={copy.write}>
          <Copy />
          {copy.status === "copied"
            ? "Copied"
            : copy.status === "failed"
              ? "Copy failed"
              : "Copy markdown"}
        </DropdownMenuItem>
        <DropdownMenuItem onSelect={() => downloadMarkdown(text, fileName)}>
          <Download />
          Download markdown
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

function CopyMarkdownButton({ text }: { text: string }) {
  const copy = useCopyMarkdown(text)

  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      aria-label={copy.status === "failed" ? "Copy failed" : "Copy markdown"}
      title={copy.status === "failed" ? "Copy failed" : "Copy all markdown"}
      onClick={copy.write}
    >
      {copy.status === "copied" ? (
        <Check className="text-emerald-600" />
      ) : (
        <Copy className={copy.status === "failed" ? "text-destructive" : ""} />
      )}
    </Button>
  )
}

function DownloadMarkdownButton({
  text,
  fileName,
}: {
  text: string
  fileName: string
}) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      aria-label="Download markdown"
      title="Download markdown"
      onClick={() => downloadMarkdown(text, fileName)}
    >
      <Download />
    </Button>
  )
}

function useCopyMarkdown(text: string) {
  const [status, setStatus] = React.useState<CopyStatus>("idle")
  const timeoutRef = React.useRef<number | null>(null)

  React.useEffect(
    () => () => {
      if (timeoutRef.current !== null) window.clearTimeout(timeoutRef.current)
    },
    []
  )

  const write = React.useCallback(() => {
    if (timeoutRef.current !== null) window.clearTimeout(timeoutRef.current)

    if (!navigator.clipboard) {
      setStatus("failed")
      timeoutRef.current = window.setTimeout(() => setStatus("idle"), 1200)
      return
    }

    navigator.clipboard.writeText(text).then(
      () => {
        setStatus("copied")
        timeoutRef.current = window.setTimeout(() => setStatus("idle"), 1200)
      },
      () => {
        setStatus("failed")
        timeoutRef.current = window.setTimeout(() => setStatus("idle"), 1200)
      }
    )
  }, [text])

  return { status, write }
}

function downloadMarkdown(text: string, fileName: string) {
  const url = URL.createObjectURL(
    new Blob([text], { type: "text/markdown;charset=utf-8" })
  )
  const anchor = document.createElement("a")
  anchor.href = url
  anchor.download = fileName
  document.body.append(anchor)
  anchor.click()
  anchor.remove()
  window.setTimeout(() => URL.revokeObjectURL(url), 0)
}

"use client"

import * as React from "react"
import ReactMarkdown, { type Components } from "react-markdown"
import rehypeRaw from "rehype-raw"
import remarkGfm from "remark-gfm"

import { Spinner } from "@/components/ui/spinner"
import { useMarkdownPageMeasurement } from "@/components/viewers/page-markdown/page-markdown-hooks"
import {
  PAGE_MARKDOWN_PAGE_PADDING_X,
  PAGE_MARKDOWN_PAGE_PADDING_Y,
  PAGE_MARKDOWN_PAGE_WIDTH,
} from "@/components/viewers/page-markdown/page-markdown-model"
import { type PageMarkdownViewMode } from "@/components/viewers/page-markdown/page-markdown-types"

export const PageMarkdownPage = React.memo(function PageMarkdownPage({
  page,
  markdown,
  mode,
  scale,
}: {
  page: number
  markdown: string
  mode: PageMarkdownViewMode
  scale: number
}) {
  const [isNearViewport, setIsNearViewport] = React.useState(false)
  const { reservedHeight, measureRef } = useMarkdownPageMeasurement({
    markdown,
    mode,
    scale,
  })

  const pageRef = React.useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return

      const cleanupMeasurement = measureRef(element)
      const root = element.closest<HTMLElement>(
        '[data-slot="scroll-area-viewport"]'
      )
      const observer = new IntersectionObserver(
        (entries) => {
          for (const entry of entries) setIsNearViewport(entry.isIntersecting)
        },
        { root, rootMargin: "200% 0px" }
      )

      observer.observe(element)
      return () => {
        observer.disconnect()
        cleanupMeasurement?.()
      }
    },
    [measureRef]
  )

  return (
    <div
      ref={pageRef}
      data-slot="page-markdown-page"
      data-page-number={page}
      className="relative w-full max-w-3xl bg-card shadow-sm ring-1 ring-border"
      style={{
        width: `${PAGE_MARKDOWN_PAGE_WIDTH * scale}px`,
        maxWidth: scale <= 1 ? "100%" : "none",
        paddingInline: `${PAGE_MARKDOWN_PAGE_PADDING_X * scale}px`,
        paddingBlock: `${PAGE_MARKDOWN_PAGE_PADDING_Y * scale}px`,
        ...(isNearViewport ? null : { height: reservedHeight }),
      }}
    >
      {isNearViewport ? (
        <PageMarkdownContent markdown={markdown} mode={mode} scale={scale} />
      ) : (
        <div className="absolute inset-0 flex items-center justify-center">
          <Spinner className="size-4 text-muted-foreground" />
        </div>
      )}
    </div>
  )
})

function PageMarkdownContent({
  markdown,
  mode,
  scale,
}: {
  markdown: string
  mode: PageMarkdownViewMode
  scale: number
}) {
  if (mode === "text") {
    return (
      <pre
        className="font-mono leading-relaxed whitespace-pre-wrap text-foreground/90"
        style={{ fontSize: `${12 * scale}px` }}
      >
        {markdown}
      </pre>
    )
  }

  return (
    <div className="leading-relaxed" style={{ fontSize: `${14 * scale}px` }}>
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        rehypePlugins={[rehypeRaw]}
        components={markdownComponents}
      >
        {markdown}
      </ReactMarkdown>
    </div>
  )
}

const markdownComponents: Components = {
  h1: (props) => (
    <h1
      className="mt-4 mb-2 text-[1.285em] font-semibold first:mt-0"
      {...props}
    />
  ),
  h2: (props) => (
    <h2
      className="mt-4 mb-2 text-[1.14em] font-semibold first:mt-0"
      {...props}
    />
  ),
  h3: (props) => (
    <h3
      className="mt-3 mb-1.5 text-[1em] font-semibold first:mt-0"
      {...props}
    />
  ),
  h4: (props) => (
    <h4 className="mt-3 mb-1.5 text-[1em] font-medium first:mt-0" {...props} />
  ),
  p: (props) => <p className="my-2 leading-relaxed" {...props} />,
  ul: (props) => <ul className="my-2 ml-5 list-disc space-y-1" {...props} />,
  ol: (props) => <ol className="my-2 ml-5 list-decimal space-y-1" {...props} />,
  li: (props) => <li className="leading-relaxed" {...props} />,
  a: (props) => (
    <a
      className="font-medium text-primary underline underline-offset-2"
      {...props}
    />
  ),
  strong: (props) => <strong className="font-semibold" {...props} />,
  hr: (props) => <hr className="my-4 border-border" {...props} />,
  blockquote: (props) => (
    <blockquote
      className="my-3 border-l-2 border-border pl-3 text-muted-foreground italic"
      {...props}
    />
  ),
  code: (props) => (
    <code
      className="rounded bg-muted px-1 py-0.5 font-mono text-[0.85em]"
      {...props}
    />
  ),
  pre: (props) => (
    <pre
      className="my-3 overflow-x-auto rounded-lg border bg-muted/50 p-3 font-mono text-[0.85em]"
      {...props}
    />
  ),
  table: (props) => (
    <div className="my-3 overflow-x-auto rounded-lg border">
      <table className="w-full border-collapse text-[0.85em]" {...props} />
    </div>
  ),
  thead: (props) => <thead className="bg-muted/60" {...props} />,
  th: (props) => (
    <th
      className="border-b border-border px-3 py-1.5 text-left font-medium [&[align=right]]:text-right"
      {...props}
    />
  ),
  td: (props) => (
    <td
      className="border-b border-border px-3 py-1.5 tabular-nums [&[align=right]]:text-right"
      {...props}
    />
  ),
}

"use client"

import * as React from "react"

import {
  createPageMeasurementKey,
  estimateMarkdownPageHeight,
  initialPagePaneState,
  resolvePagePaneReport,
  type PagePane,
  type PendingPageScroll,
} from "@/components/viewers/page-markdown/page-markdown-model"
import { type PageMarkdownViewMode } from "@/components/viewers/page-markdown/page-markdown-types"

export function useMarkdownPageMeasurement({
  markdown,
  mode,
  scale,
}: {
  markdown: string
  mode: PageMarkdownViewMode
  scale: number
}) {
  const key = createPageMeasurementKey({ markdown, mode, scale })
  const [measurement, setMeasurement] = React.useState<{
    key: string
    height: number | null
  }>({ key, height: null })

  React.useEffect(() => {
    setMeasurement({ key, height: null })
  }, [key])

  const measureRef = React.useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return

      const observer = new ResizeObserver(() => {
        if (element.offsetHeight > 0) {
          setMeasurement({ key, height: element.offsetHeight })
        }
      })

      observer.observe(element)
      return () => observer.disconnect()
    },
    [key]
  )

  return {
    reservedHeight:
      measurement.key === key && measurement.height !== null
        ? measurement.height
        : estimateMarkdownPageHeight(markdown, scale),
    measureRef,
  }
}

export function usePagePaneSync({
  onMarkdownPageChange,
}: {
  onMarkdownPageChange?: (page: number) => void
}) {
  const [state, setState] = React.useState(initialPagePaneState)
  const stateRef = React.useRef(state)
  const pendingRef = React.useRef<PendingPageScroll | null>(null)

  React.useEffect(() => {
    stateRef.current = state
  }, [state])

  const reportPage = React.useCallback(
    (pane: PagePane, page: number) => {
      const transition = resolvePagePaneReport({
        state: stateRef.current,
        pending: pendingRef.current,
        pane,
        page,
      })

      stateRef.current = transition.state
      pendingRef.current = transition.pending
      setState(transition.state)

      if (pane === "markdown") {
        onMarkdownPageChange?.(transition.state.page)
      }

      return transition.scrollTarget
    },
    [onMarkdownPageChange]
  )

  return {
    currentPage: state.page,
    reportMarkdownPage: React.useCallback(
      (page: number) => reportPage("markdown", page),
      [reportPage]
    ),
    reportDocumentPage: React.useCallback(
      (page: number) => reportPage("document", page),
      [reportPage]
    ),
  }
}

export const PAGE_MARKDOWN_PAGE_WIDTH = 768
export const PAGE_MARKDOWN_PAGE_PADDING_X = 36
export const PAGE_MARKDOWN_PAGE_PADDING_Y = 28
export const PAGE_MARKDOWN_SCALE_MIN = 0.35
export const PAGE_MARKDOWN_SCALE_MAX = 3
export const PAGE_MARKDOWN_FIT_SCALE_MAX = 1.5
export const PAGE_MARKDOWN_FIT_HORIZONTAL_PADDING = 32
export const PAGE_MARKDOWN_COMPACT_ACTIONS_WIDTH = 460

export type PagePane = "markdown" | "document"

export interface PagePaneState {
  page: number
  pane: PagePane
  version: number
}

export interface PendingPageScroll {
  pane: PagePane
  page: number
  version: number
}

export interface PagePaneTransition {
  state: PagePaneState
  pending: PendingPageScroll | null
  scrollTarget: PendingPageScroll | null
  confirmed: boolean
}

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value))
}

export function clampPageScale(scale: number): number {
  return clamp(scale, PAGE_MARKDOWN_SCALE_MIN, PAGE_MARKDOWN_SCALE_MAX)
}

export function fitPageScale(containerWidth: number | null): number {
  if (!containerWidth) return 1
  return clamp(
    (containerWidth - PAGE_MARKDOWN_FIT_HORIZONTAL_PADDING) /
      PAGE_MARKDOWN_PAGE_WIDTH,
    PAGE_MARKDOWN_SCALE_MIN,
    PAGE_MARKDOWN_FIT_SCALE_MAX
  )
}

export function zoomPageScale(scale: number, factor: number): number {
  return clampPageScale(scale * factor)
}

export function estimateMarkdownPageHeight(
  markdown: string,
  scale: number
): number {
  const lineCount = markdown.split("\n").length
  return Math.min(
    1800 * scale,
    Math.max(180 * scale, lineCount * 26 * scale + 80 * scale)
  )
}

export function joinMarkdownPages(pages: string[]): string {
  return pages.join("\n\n")
}

export function createPageMeasurementKey({
  markdown,
  mode,
  scale,
}: {
  markdown: string
  mode: string
  scale: number
}): string {
  return `${mode}:${scale.toFixed(3)}:${markdown.length}:${markdown.slice(0, 24)}:${markdown.slice(-24)}`
}

export function initialPagePaneState(): PagePaneState {
  return { page: 1, pane: "markdown", version: 0 }
}

export function resolvePagePaneReport({
  state,
  pending,
  pane,
  page,
}: {
  state: PagePaneState
  pending: PendingPageScroll | null
  pane: PagePane
  page: number
}): PagePaneTransition {
  const nextPage = Math.max(1, Math.floor(page))

  if (pending?.pane === pane && pending.page === nextPage) {
    return {
      state: { page: nextPage, pane, version: state.version + 1 },
      pending: null,
      scrollTarget: null,
      confirmed: true,
    }
  }

  if (!pending && state.page === nextPage) {
    return {
      state,
      pending: null,
      scrollTarget: null,
      confirmed: false,
    }
  }

  const targetPane: PagePane = pane === "markdown" ? "document" : "markdown"
  const nextState = { page: nextPage, pane, version: state.version + 1 }
  const nextPending = {
    pane: targetPane,
    page: nextPage,
    version: nextState.version,
  }

  return {
    state: nextState,
    pending: nextPending,
    scrollTarget: nextPending,
    confirmed: false,
  }
}

"use client"

import * as React from "react"

export function useElementWidth<T extends HTMLElement = HTMLDivElement>(): [
  React.RefCallback<T>,
  number | null,
] {
  const cleanupRef = React.useRef<(() => void) | null>(null)
  const [width, setWidth] = React.useState<number | null>(null)

  const ref = React.useCallback((element: T | null) => {
    cleanupRef.current?.()
    cleanupRef.current = null

    if (!element) return

    setWidth(element.clientWidth)
    let frame = 0
    let nextWidth = element.clientWidth
    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        nextWidth = (entry.target as HTMLElement).clientWidth
      }
      if (frame) return
      frame = requestAnimationFrame(() => {
        frame = 0
        setWidth(nextWidth)
      })
    })

    observer.observe(element)
    cleanupRef.current = () => {
      if (frame) cancelAnimationFrame(frame)
      observer.disconnect()
    }
  }, [])

  React.useEffect(() => () => cleanupRef.current?.(), [])

  return [ref, width]
}

